<script setup>
import { ref,watch } from 'vue';
import { libraryApi } from '@/services/library.js';
import { ExternalLink,Download,RotateCcw } from '@/components/app/icons.js';
const props=defineProps({unitId:String,compact:Boolean});
const unit=ref(null),error=ref(''),loading=ref(false),imageError=ref(false),attempt=ref(0);let generation=0;
async function load(){const id=props.unitId,version=++generation;unit.value=null;error.value='';imageError.value=false;attempt.value++;if(!id){error.value='没有指定原文位置，请从案例出处重新打开。';return}loading.value=true;try{const result=await libraryApi.unit(id);if(version===generation)unit.value=result}catch(e){if(version===generation)error.value=e.message}finally{if(version===generation)loading.value=false}}
watch(()=>props.unitId,load,{immediate:true});
</script>
<template><section class="source-reader"><ElSkeleton v-if="loading" animated :rows="3" aria-label="读取原文中…"/><div v-else-if="error"><AppAlert type="error" role="alert" class="form-error">{{ error }}</AppAlert><AppButton variant="outline" @click="load"><RotateCcw :size="15" />重试</AppButton></div><template v-else-if="unit"><div class="source-reader-heading"><div v-if="!compact"><h2>{{ unit.materialTitle }}</h2><span>{{ unit.label }}</span></div><div class="admin-source-actions"><InfoTip v-if="(compact&&(unit.metadata.author||unit.metadata.sourceNote))||!unit.imageUrl" label="材料信息"><span v-if="compact">{{[unit.metadata.author,unit.metadata.sourceNote].filter(Boolean).join(' 　 ')}}</span><span v-if="!unit.imageUrl">文字视图保留内容；请按来源类型核对原文件或项目整理稿。</span></InfoTip><ElLink :underline="false" :href="unit.originalUrl" target="_blank" rel="noopener"><Download :size="16"/>{{unit.metadata.curatedSummary?'中文整理稿':'原文件'}}</ElLink></div></div><p v-if="!compact&&(unit.metadata.author || unit.metadata.sourceNote)" class="ops-source-credit">{{ [unit.metadata.author,unit.metadata.sourceNote].filter(Boolean).join(' 　 ') }}</p><ElLink :underline="false" v-if="unit.metadata.sourceUrl" :href="unit.metadata.sourceUrl" target="_blank" rel="noopener" class="source-external">来源链接<ExternalLink :size="14" /></ElLink><ElLink :underline="false" v-if="unit.imageUrl" :href="unit.imageUrl+'?inline=1'" target="_blank" rel="noopener" class="original-preview"><AppImage :src="unit.imageUrl+'?read='+attempt" @error="imageError=true" :alt="unit.materialTitle+' '+unit.label" /></ElLink><Surface data-ui="card" v-else class="source-document"><p class="model-prose">{{ unit.originalText }}</p></Surface><div v-if="imageError"><AppAlert type="error" role="alert" class="form-error">原文图片读取失败，请重试或下载原文件。</AppAlert><AppButton variant="outline" @click="load">重试原文图片</AppButton></div><AppDisclosure v-if="unit.text!==unit.originalText"><template #title>修订后的识别文本</template><p class="model-prose">{{ unit.text }}</p></AppDisclosure></template></section></template>
